"""Lexer for the jq language.

The scanner follows the token spellings and string rules in ``sources/lexer.l``.
Tokens retain both an absolute offset and a one-based line/column location so
the parser can produce useful diagnostics without reparsing source text.
"""

from __future__ import annotations

from dataclasses import dataclass
import json
import re


@dataclass(frozen=True)
class Token:
    kind: str
    value: str
    position: int
    line: int = 1
    column: int = 1

    @property
    def text(self) -> str:
        """Compatibility alias for callers that call token spelling ``text``."""
        return self.value


class LexError(ValueError):
    """Raised when source cannot be converted into jq tokens."""


_KEYWORDS = {
    "as", "def", "if", "then", "else", "elif", "end", "reduce", "foreach",
    "and", "or", "try", "catch", "label", "break", "import", "include", "module",
}
_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_QUALIFIED = re.compile(r"(?:[A-Za-z_][A-Za-z0-9_]*::)*[A-Za-z_][A-Za-z0-9_]*")
_NUMBER = re.compile(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?")
_FORMATS = re.compile(r"@[A-Za-z0-9_]+")
_OPERATORS = (
    "?//", "//=", "|=", "+=", "-=", "*=", "/=", "%=", "==", "!=", "<=", ">=", "..", "//",
)
_SINGLE = set(".?=;,|:+-*/%<>()[]{}")
_ESCAPES = set('"\\/bfnrt')


def _location(source: str, position: int) -> tuple[int, int]:
    line = source.count("\n", 0, position) + 1
    prior = source.rfind("\n", 0, position)
    return line, position - prior


def _token(kind: str, value: str, source: str, position: int) -> Token:
    line, column = _location(source, position)
    return Token(kind, value, position, line, column)


def _decode_string(raw: str, source: str, position: int) -> str:
    try:
        return json.loads('"' + raw + '"')
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise LexError(f"invalid string escape at position {position}") from exc


def _interpolation_end(source: str, start: int) -> int:
    """Return the index of the ')' closing an interpolation starting at *start*."""
    depth = 0
    i = start
    while i < len(source):
        if source[i] == '"':
            i = _quoted_end(source, i)
            continue
        if source[i] == "#":
            newline = source.find("\n", i)
            i = len(source) if newline < 0 else newline + 1
            continue
        if source[i] == "(":
            depth += 1
        elif source[i] == ")":
            if depth == 0:
                return i
            depth -= 1
        i += 1
    raise LexError(f"unterminated string interpolation at position {start - 2}")


def _quoted_end(source: str, opening: int) -> int:
    i = opening + 1
    while i < len(source):
        if source[i] == "\\":
            i += 2
        elif source[i] == '"':
            return i + 1
        else:
            i += 1
    raise LexError(f"unterminated string at position {opening}")


def _scan_string(source: str, opening: int) -> tuple[list[Token], int, bool]:
    """Scan a quoted string, returning tokens, next offset, and interpolation flag."""
    i = opening + 1
    text_start = i
    parts: list[Token] = []
    interpolated = False
    while i < len(source):
        char = source[i]
        if char == '"':
            if interpolated or i != text_start:
                if i > text_start:
                    parts.append(_token("qqstring_text", _decode_string(source[text_start:i], source, text_start), source, text_start))
            if interpolated:
                parts.append(_token("qqstring_end", '"', source, i))
                return parts, i + 1, True
            return [_token("string", _decode_string(source[text_start:i], source, text_start), source, opening)], i + 1, False
        if char == "\\" and i + 1 < len(source) and source[i + 1] == "(":
            if not interpolated:
                parts.append(_token("qqstring_start", '"', source, opening))
            if i > text_start:
                parts.append(_token("qqstring_text", _decode_string(source[text_start:i], source, text_start), source, text_start))
            end = _interpolation_end(source, i + 2)
            parts.append(_token("interpolation_start", "\\(", source, i))
            parts.extend(tokenize(source[i + 2:end], _offset=i + 2)[:-1])
            parts.append(_token("interpolation_end", ")", source, end))
            interpolated = True
            i = end + 1
            text_start = i
            continue
        if char == "\\":
            if i + 1 >= len(source):
                raise LexError(f"invalid string escape at position {i}")
            if source[i + 1] == "u":
                if not re.match(r"[0-9A-Fa-f]{4}", source[i + 2:i + 6]):
                    raise LexError(f"invalid unicode escape at position {i}")
                i += 6
            elif source[i + 1] in _ESCAPES:
                i += 2
            else:
                raise LexError(f"invalid string escape at position {i}")
        else:
            if ord(char) < 0x20:
                raise LexError(f"unescaped control character at position {i}")
            i += 1
    raise LexError(f"unterminated string at position {opening}")


def tokenize(source: str, *, _offset: int = 0) -> list[Token]:
    """Tokenize jq source, raising :class:`LexError` on lexical errors."""
    if _offset:
        # Interpolation token positions are absolute in the original source.
        local = tokenize(source, _offset=0)
        return [Token(t.kind, t.value, t.position + _offset, t.line, t.column + _offset) for t in local]
    tokens: list[Token] = []
    delimiters: list[str] = []
    i = 0
    while i < len(source):
        c = source[i]
        if c.isspace():
            i += 1
            continue
        if c == "#":
            while True:
                newline = source.find("\n", i)
                if newline < 0:
                    i = len(source)
                    break
                backslashes = 0
                cursor = newline - 1
                while cursor >= i and source[cursor] == "\\":
                    backslashes += 1
                    cursor -= 1
                i = newline + 1
                if backslashes % 2 == 0:
                    break
            continue
        if c == '"':
            string_tokens, i, _ = _scan_string(source, i)
            tokens.extend(string_tokens)
            continue
        match = _FORMATS.match(source, i)
        if match:
            tokens.append(_token("format", match.group()[1:], source, i)); i = match.end(); continue
        match = _NUMBER.match(source, i)
        if match:
            value = match.group(); tokens.append(_token("number", value, source, i)); i = match.end(); continue
        if c == "." and i + 1 < len(source) and (source[i + 1].isalpha() or source[i + 1] == "_"):
            match = _NAME.match(source, i + 1); assert match
            value = match.group(); tokens.append(_token("field", value, source, i)); i = match.end(); continue
        if c == "$":
            match = _QUALIFIED.match(source, i + 1)
            if not match:
                raise LexError(f"invalid binding at position {i}")
            value = match.group(); tokens.append(_token("binding", value, source, i)); i = match.end(); continue
        match = _QUALIFIED.match(source, i)
        if match:
            value = match.group(); tokens.append(_token("word", value, source, i)); i = match.end(); continue
        operator = next((op for op in _OPERATORS if source.startswith(op, i)), None)
        if operator:
            tokens.append(_token("operator", operator, source, i)); i += len(operator); continue
        if c in _SINGLE:
            if c in "([{": delimiters.append({"(": ")", "[": "]", "{": "}"}[c])
            elif c in ")]}":
                if not delimiters or delimiters.pop() != c:
                    raise LexError(f"mismatched closing delimiter at position {i}")
            tokens.append(_token("delimiter" if c in "()[]{}" else "operator", c, source, i)); i += 1; continue
        raise LexError(f"unexpected character at position {i}")
    if delimiters:
        raise LexError("unterminated delimiter")
    tokens.append(_token("eof", "", source, len(source)))
    return tokens

import inspect
import json
import subprocess
import sys
from pathlib import Path
import unittest

import jq_lexer
import jq_parser
import jq_runtime


ROOT = Path(__file__).resolve().parents[1]


class ArchitectureTests(unittest.TestCase):
    def test_public_module_contracts(self) -> None:
        self.assertTrue(callable(jq_lexer.tokenize))
        self.assertTrue(callable(jq_parser.parse))
        self.assertTrue(callable(jq_runtime.evaluate))
        self.assertTrue(inspect.isgeneratorfunction(jq_runtime.evaluate))

    def test_generator_preserves_comma_order(self) -> None:
        program = jq_parser.parse("1, .")
        self.assertEqual(list(jq_runtime.evaluate(program, 2)), [1, 2])

    def test_cli_compact_output(self) -> None:
        result = subprocess.run(
            [str(ROOT / "jq"), "-c", "."],
            input='{"a": 1}\n', text=True, capture_output=True, check=False,
        )
        self.assertEqual(result.returncode, 0)
        self.assertEqual(json.loads(result.stdout), {"a": 1})

    def test_cli_compile_failure_status(self) -> None:
        result = subprocess.run(
            [str(ROOT / "jq"), "-c", "("],
            input="null\n", text=True, capture_output=True, check=False,
        )
        self.assertEqual(result.returncode, 3)


if __name__ == "__main__":
    unittest.main()
"""Process boundary for the standalone jq executable."""

from __future__ import annotations

import argparse
import json
import sys
from collections.abc import Sequence
from typing import Any

from jq_parser import ParseError, parse
from jq_runtime import RuntimeFailure, evaluate


def _arguments(arguments: Sequence[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(prog="jq")
    parser.add_argument("-c", dest="program", required=True)
    return parser.parse_args(arguments)


def main(arguments: Sequence[str] | None = None) -> int:
    """Run jq's compact stdin/stdout protocol and return its process status."""
    try:
        options = _arguments(sys.argv[1:] if arguments is None else arguments)
        program = parse(options.program)
    except (ParseError, ValueError, SystemExit) as error:
        if isinstance(error, SystemExit):
            return int(error.code or 0)
        print(f"jq: compile error: {error}", file=sys.stderr)
        return 3

    try:
        for line in sys.stdin:
            if not line.strip():
                continue
            value: Any = json.loads(line)
            for result in evaluate(program, value):
                print(json.dumps(result, separators=(",", ":"), ensure_ascii=False))
    except (json.JSONDecodeError, RuntimeFailure, TypeError, ValueError) as error:
        print(f"jq: runtime error: {error}", file=sys.stderr)
        return 5
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Precedence-aware front end for the executable jq architecture."""

from __future__ import annotations

from dataclasses import dataclass
import json

from jq_lexer import Token, tokenize


class ParseError(ValueError):
    """Raised for syntax and static errors."""


@dataclass(frozen=True)
class Node:
    kind: str
    value: object = None
    children: tuple["Node", ...] = ()


class Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.index = 0

    def current(self) -> Token:
        return self.tokens[self.index]

    def take(self) -> Token:
        token = self.current()
        self.index += 1
        return token

    def expression(self) -> Node:
        left = self.term()
        if self.current().value in {"|", ","}:
            operator = self.take().value
            right = self.expression()
            return Node(operator, children=(left, right))
        return left

    def term(self) -> Node:
        token = self.take()
        if token.kind == "eof":
            raise ParseError("expected filter")
        if token.value == ".":
            if self.current().value == "[":
                self.take()
                if self.current().value != "]":
                    raise ParseError("only empty iterator syntax is supported by this boundary")
                self.take()
                return Node("iterate")
            return Node("identity")
        if token.kind == "number":
            return Node("literal", json.loads(token.value))
        if token.kind == "string":
            return Node("literal", token.value)
        if token.kind in {"word", "keyword"} and token.value in {"true", "false", "null", "empty"}:
            return Node(token.value)
        if token.value == "(":
            value = self.expression()
            if self.take().value != ")":
                raise ParseError("expected closing parenthesis")
            return value
        raise ParseError(f"unexpected token at position {token.position}")


def parse(source: str) -> Node:
    """Parse jq source into an AST suitable for :func:`jq_runtime.evaluate`."""
    parser = Parser(tokenize(source))
    tree = parser.expression()
    if parser.current().kind != "eof":
        raise ParseError(f"unexpected token at position {parser.current().position}")
    return tree
"""Generator-based jq evaluation boundary."""


class RuntimeFailure(RuntimeError):
    """Raised after compilation when a filter cannot evaluate its input."""


def _walk(node, value):
    if node.kind == "identity":
        yield value
    elif node.kind == "literal":
        yield node.value
    elif node.kind == "true":
        yield True
    elif node.kind == "false":
        yield False
    elif node.kind == "null":
        yield None
    elif node.kind == "empty":
        return
    elif node.kind == ",":
        yield from _walk(node.children[0], value)
        yield from _walk(node.children[1], value)
    elif node.kind == "|":
        for intermediate in _walk(node.children[0], value):
            yield from _walk(node.children[1], intermediate)
    elif node.kind == "iterate":
        if isinstance(value, list):
            yield from value
        elif isinstance(value, dict):
            yield from value.values()
        else:
            raise RuntimeFailure("cannot iterate over this value")
    else:
        raise RuntimeFailure(f"unknown AST node: {node.kind}")


def evaluate(program, value):
    """Evaluate an AST against one input, preserving ordered generator semantics."""
    yield from _walk(program, value)
import unittest

import jq_lexer


class LexerTests(unittest.TestCase):
    def test_basic_source_has_identity_field_number_and_pipe(self) -> None:
        tokens = list(jq_lexer.tokenize(".foo | 42"))
        self.assertGreaterEqual(len(tokens), 4)
        self.assertTrue(all(token.kind for token in tokens))
        self.assertEqual([(token.kind, token.value) for token in tokens[:-1]],
                         [("field", "foo"), ("operator", "|"), ("number", "42")])

    def test_format_token(self) -> None:
        token = jq_lexer.tokenize("@json")[0]
        self.assertEqual((token.kind, token.value), ("format", "json"))

    def test_binding_token(self) -> None:
        token = jq_lexer.tokenize("$item")[0]
        self.assertEqual((token.kind, token.value), ("binding", "item"))

    def test_invalid_escape_is_rejected(self) -> None:
        with self.assertRaises(jq_lexer.LexError):
            jq_lexer.tokenize(r'"u\vw"')

    def test_interpolation_and_comment_continuation(self) -> None:
        tokens = jq_lexer.tokenize('"value=\\(.)" # ignored \\\n+  still ignored\n')
        self.assertEqual([token.kind for token in tokens],
                         ["qqstring_start", "qqstring_text", "interpolation_start",
                          "operator", "interpolation_end", "qqstring_end", "eof"])

    def test_mismatched_delimiter_is_rejected(self) -> None:
        with self.assertRaises(jq_lexer.LexError):
            jq_lexer.tokenize("[1}")


if __name__ == "__main__":
    unittest.main()

